17: impl PgBackend {
18:     /// Build from `DATABASE_URL` environment variable.
19:     ///
20:     /// Expects a standard Postgres connection URL:
21:     /// `postgres://user:password@host:port/dbname`
22:     ///
23:     /// # Errors
24:     ///
25:     /// Returns [`PgError::Config`] when the `DATABASE_URL` environment
26:     /// variable is unset, or when `deadpool_postgres` rejects the connection
27:     /// string / fails to build the pool.
28:     pub fn from_env() -> Result<Self, PgError> {
29:         let database_url = std::env::var("DATABASE_URL")
30:             .map_err(|_| PgError::Config("DATABASE_URL must be set".into()))?;
31: 
32:         let mut cfg = PoolConfig::new();
33:         cfg.url = Some(database_url);
34: 
35:         let pool = cfg
36:             .create_pool(Some(Runtime::Tokio1), tokio_postgres::NoTls)
37:             .map_err(|e| PgError::Config(e.to_string()))?;
38: 
39:         Ok(Self { pool })
40:     }
41: }
