48:     ///
49:     /// ```sql
50:     /// SET LOCAL ROLE <role>;
51:     /// SET LOCAL "request.jwt.claims" = '<claims_json>';
52:     /// SET LOCAL "request.headers"    = '{"authorization":"Bearer <raw_bearer>"}';
53:     /// SET LOCAL "app.jwt_claims"     = '<claims_json>';
54:     /// SET LOCAL "app.keto_subject"   = '<keto_subject>';
55:     /// SET LOCAL "app.vault_key_id"   = '<vault_key_id>';
56:     /// ```
57:     ///
58:     /// The returned `Conn` keeps the connection alive for the duration of the
59:     /// caller's use. Callers MUST NOT log the `RlsContext` — it contains the
60:     /// raw bearer token and subject identifiers.
